                  !$omp parallel default(shared) private(IX,val,a,b,c,d,i,j,k,l,x,y,u,v,w,z,r,s,t,g,h,idet,jdet,jj,kdx,idx)
                  allocate(IX(nob,nua))
                  !$omp do schedule(dynamic,8)
                  do kdx = 1, tnblk
                     if (toff(kdx+1)-1 < toff(kdx)) cycle
                     ! -0.25 * I3C_vovvoo(axcylk) * taab(bydjix), q = (b,c,k,l), sign -1
                     idet = toff(kdx)
                     b = t4c_excits(idet,2); c = t4c_excits(idet,3); k = t4c_excits(idet,7); l = t4c_excits(idet,8);
                     IX = 0.0d0
                     do u = 1, noa
                        IX(:,:) = IX(:,:) + (-1d0 * t2b(b,c,u,k)) * H2B_oovo_1203(:,:,u,l)
                     end do
                     do u = 1, nub
                        IX(:,:) = IX(:,:) + (1d0 * t2c(c,u,k,l)) * H2B_vovv_1203(:,:,b,u)
                     end do
                     do u = 1, noa
                        IX(:,:) = IX(:,:) + (1d0 * t2b(b,c,u,l)) * H2B_oovo_1203(:,:,u,k)
                     end do
                     do idet = toff(kdx), toff(kdx+1)-1
                        a = t4c_excits(idet,1); d = t4c_excits(idet,4); i = t4c_excits(idet,5); j = t4c_excits(idet,6);
                        val = 0.0d0
                        idx = pspace_find(key_vaab1120, nblk_vaab1120, pspace_key((/a,d,i,j/), 4, vdims_vaab1120, vchain_vaab1120))
                        if (idx/=0) then
                        do jdet = off_vaab1120(idx), off_vaab1120(idx+1)-1
                           y = vaab1120_excits(jdet,5); x = vaab1120_excits(jdet,6)
                           val = val + vaab1120_amps(jdet) * ((-1)*IX(x,y))
                        end do
                        end if
                        resid(idet) = resid(idet) + 1d0 * val
                     end do
                  end do
                  !$omp end do
                  deallocate(IX)
                  !$omp end parallel
                  !!!! 1 passes on T4 sorted by columns (2,4,7,8)
                  tdims(1:4) = (/nua,nub,nob,nob/)
                  tchain(1:4) = (/.false.,.false.,.false.,.true./)
                  call sort_pspace(t4c_excits, t4c_amps, n4aabb, 4, (/2,4,7,8/), tdims, tchain, tnblk, tkey, toff, resid)
                  !$omp parallel default(shared) private(IX,val,a,b,c,d,i,j,k,l,x,y,u,v,w,z,r,s,t,g,h,idet,jdet,jj,kdx,idx)
                  allocate(IX(nob,nua))
                  !$omp do schedule(dynamic,8)
                  do kdx = 1, tnblk
                     if (toff(kdx+1)-1 < toff(kdx)) cycle
                     ! -0.25 * I3C_vovvoo(axcylk) * taab(bydjix), q = (b,d,k,l), sign +1
                     idet = toff(kdx)
                     b = t4c_excits(idet,2); d = t4c_excits(idet,4); k = t4c_excits(idet,7); l = t4c_excits(idet,8);
                     IX = 0.0d0
                     do u = 1, noa
                        IX(:,:) = IX(:,:) + (-1d0 * t2b(b,d,u,k)) * H2B_oovo_1203(:,:,u,l)
                     end do
                     do u = 1, nub
                        IX(:,:) = IX(:,:) + (1d0 * t2c(d,u,k,l)) * H2B_vovv_1203(:,:,b,u)
                     end do
                     do u = 1, noa
                        IX(:,:) = IX(:,:) + (1d0 * t2b(b,d,u,l)) * H2B_oovo_1203(:,:,u,k)
                     end do
                     do idet = toff(kdx), toff(kdx+1)-1
                        a = t4c_excits(idet,1); c = t4c_excits(idet,3); i = t4c_excits(idet,5); j = t4c_excits(idet,6);
                        val = 0.0d0
                        idx = pspace_find(key_vaab1120, nblk_vaab1120, pspace_key((/a,c,i,j/), 4, vdims_vaab1120, vchain_vaab1120))
                        if (idx/=0) then
                        do jdet = off_vaab1120(idx), off_vaab1120(idx+1)-1
                           y = vaab1120_excits(jdet,5); x = vaab1120_excits(jdet,6)
                           val = val + vaab1120_amps(jdet) * ((-1)*IX(x,y))
                        end do
                        end if
                        resid(idet) = resid(idet) - 1d0 * val
                     end do
                  end do
                  !$omp end do
                  deallocate(IX)
                  !$omp end parallel
                  deallocate(vaab0121_amps,vaab0121_excits,key_vaab0121,off_vaab0121)
                  deallocate(vaab2101_amps,vaab2101_excits,key_vaab2101,off_vaab2101)
                  deallocate(vaab1021_amps,vaab1021_excits,key_vaab1021,off_vaab1021)
                  deallocate(vabb1201_amps,vabb1201_excits,key_vabb1201,off_vabb1201)
                  deallocate(vabb1012_amps,vabb1012_excits,key_vabb1012,off_vabb1012)
                  deallocate(vabb1210_amps,vabb1210_excits,key_vabb1210,off_vabb1210)
                  deallocate(vabb0112_amps,vabb0112_excits,key_vabb0112,off_vabb0112)
                  deallocate(vaab2110_amps,vaab2110_excits,key_vaab2110,off_vaab2110)
                  deallocate(vaaa22_amps,vaaa22_excits,key_vaaa22,off_vaaa22)
                  deallocate(vaab2020_amps,vaab2020_excits,key_vaab2020,off_vaab2020)
                  deallocate(vabb0202_amps,vabb0202_excits,key_vabb0202,off_vabb0202)
                  deallocate(vbbb22_amps,vbbb22_excits,key_vbbb22,off_vbbb22)
                  deallocate(vaab1111_amps,vaab1111_excits,key_vaab1111,off_vaab1111)
                  deallocate(vabb1111_amps,vabb1111_excits,key_vabb1111,off_vabb1111)
                  deallocate(vaab1120_amps,vaab1120_excits,key_vaab1120,off_vaab1120)
                  deallocate(vabb1102_amps,vabb1102_excits,key_vabb1102,off_vabb1102)
                  deallocate(vabb0211_amps,vabb0211_excits,key_vabb0211,off_vabb0211)
                  deallocate(vaab2011_amps,vaab2011_excits,key_vaab2011,off_vaab2011)
                  call release_sort_workspace()
              end subroutine t4c_p_b3

end module ccsdtq_p_t4c_p_b3
